        CT.checkTrue("the reply says where it came from, and the question needs the whole message (the matcher is the engine's)", chat.contains("reply.caption = caption") && chat.contains("\"From NotchMeow, on this Mac\"") && chat.contains("engine.status(for: query)"))
        CT.checkTrue("the chip is in the chat's empty state, once", count("SidekickStatusChip(state: state)", in: view) == 1 && view.contains("SidekickStatusChip(state: state)   // the empty chat's one chip") && code(source("SidekickChat.swift")).contains("if !engine.liveAgents.isEmpty {"))
        CT.checkTrue("the chip observes the engine's published live agents and no longer reads a plain property", code(source("SidekickChat.swift")).contains("@ObservedObject private var engine = Sidekick.shared.engine") && !code(source("SidekickChat.swift")).contains("Sidekick.shared.liveAgents") && code(source("SidekickEngine.swift")).contains("@Published private(set) var liveAgents: Set<String> = []") && count("var liveAgents", in: code(source("SidekickEngine.swift"))) == 1)

        CT.checkTrue("the answer is shown as its words: the chat bubble renders Markdown, so the lines and a nicer sentence go through SK.markdownPlain first", count("SK.markdownPlain(", in: code(chat)) == 2 && code(chat).contains("content: SK.markdownPlain(answered.lines.joined(separator: \"\\n\"))") && code(chat).contains("state.chatHistory[i].content = SK.markdownPlain(nicer)"))

        CT.section("Retry and Try again act on the real reply: a status answer's two rows are never the message the model answered")
        let retryBody = body(claude, from: "func retryLast(state: AppState) {", to: "\n    }\n")
        let resendBody = body(claude, from: "func resendLastMessage(state: AppState) {", to: "\n    }\n")
        CT.checkTrue("Retry drops the newest reply that is not a status answer", !retryBody.isEmpty && retryBody.contains("$0.role == .assistant && $0.caption != SidekickChat.caption") && !retryBody.contains("lastIndex(where: { $0.role == .assistant })"))
        CT.checkTrue("Try again resends the newest message that is not a status question", !resendBody.isEmpty && resendBody.contains("Self.isStatusQuestion(rows, at: $0)") && !resendBody.contains("lastIndex(where: { $0.role == .user })"))
        CT.checkTrue("a status question is a user row that an answer with SidekickChat.caption follows, and that is the one test for it", claude.contains("static func isStatusQuestion(_ rows: [ChatMessage], at i: Int) -> Bool") && claude.contains("rows[i + 1].caption == SidekickChat.caption"))

        CT.section("Settings → Sidekick: a new section in the existing style, and nothing existing is restyled")
        let settingsView = source("SettingsView.swift"), sidekickSettings = source("SidekickSettingsView.swift")
        let routeTabs = source("SettingsRoute.swift").components(separatedBy: "enum Tab").dropFirst().first?.components(separatedBy: "    }").first ?? ""
        CT.checkTrue("Settings shows the Sidekick as a tab of AI and chat: the Tab enum names it, and the view draws SidekickSettingsSection once", routeTabs.contains("sidekick") && count("SidekickSettingsSection()", in: settingsView) == 1)
        CT.checkTrue("the rows are the spec's: the master switch, the local voice with what was found, the muted kinds with Unmute, and the permission line locked on", sidekickSettings.contains("SwitchRow(\"Show notes from the sidekick\"") && sidekickSettings.contains("store.setLocal(") && sidekickSettings.contains("\"Found: \\($0)\"") && sidekickSettings.contains("\"No local model found\"") && sidekickSettings.contains("\"Nothing is muted\"") && sidekickSettings.contains("Button(\"Unmute\") { store.unmute(row.kind) }") && sidekickSettings.contains("store.mute(") && sidekickSettings.contains("SettingsSidekick.permissionLine") && sidekickSettings.contains("isOn: .constant(true), disabled: true"))
        CT.checkTrue("the five kinds are listed by the names the spec gives", ["Away recaps", "Repeated steps", "Repeated errors", "Waiting for your OK", "Gone quiet"].allSatisfy { sidekickSettings.contains("\"\($0)\"") })
        CT.checkTrue("every change goes through the store, and the permission line and the badge have no switch here", sidekickSettings.contains("store.setOn($0)") && sidekickSettings.contains("store.setLocal($0)") && !sidekickSettings.contains("risk") && !sidekickSettings.contains("badge"))

        CT.checkTrue("the voice's provider factory is built with the servers on this computer only: no cloud key, and the Keychain is never read on this path", code(voiceApp).contains("ProviderFactory(servers: servers") && !code(voiceApp).contains("keys") && !voiceApp.contains("KeychainStore") && !voiceApp.contains("AIService.shared.key(") && !voiceApp.contains("AIService.shared.factory()"))

        CT.section("the sidekick only reads: it answers nothing, starts no timer of its own, logs nothing, and writes, sends and reads nothing but a clipboard path")
        // Tokens no sidekick file may hold (strict: a comment is not exempt): a hook answer, a log, a print, a network call, a file read or write, a timer, a sleep or a clock of its own.
        let never = ["sendApprovalDecision", "sendLine", "permissionDecision", "appendAppLog", "nbLog", "print(", "NSLog", "Logger", "os_log", "URLSession", "URLRequest", "NWConnection", ".write(", "FileManager", "FileHandle", "contentsOf", "InputStream", "transcript_path", "Process(", "Timer", "repeats", "makeTimerSource", "scheduledTimer", "ContinuousClock", "CADisplayLink", "CVDisplayLink", "usleep", "Thread.sleep"]
        // The file's text for the token pins: every line but a whole-line comment (a comment that names a word is not a use of it; a line of code is read in full).
        func live(_ f: String) -> String { source(f).components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).hasPrefix("//") }.joined(separator: "\n") }
        for f in sidekickFiles {
            // SidekickStore and SidekickSettings own the three UserDefaults keys (pinned below); no other file may name UserDefaults.
            let forbidden = f == "SidekickStore.swift" || f == "SidekickSettings.swift" ? never : never + ["UserDefaults"]
            // `append(contentsOf:)` is an array's own method, not a file read: the only exemption, pinned to the three files that use it below.
            let text = live(f).replacingOccurrences(of: "append(contentsOf:", with: "")
            CT.check("\(f): none of the forbidden tokens", forbidden.filter { text.contains($0) }, [])
        }
        CT.check("the array's own append(contentsOf:) is used in exactly these three files, and nowhere a file is read", sidekickFiles.filter { live($0).contains("append(contentsOf:") }, ["SidekickExplain.swift", "SidekickLedger.swift", "SidekickText.swift"])
        // The exceptions the real code needs, each pinned to exactly one occurrence in its file and to none in any other, counted in code (a comment is not counted).
        let exact: [(file: String, token: String)] = [("Sidekick.swift", "asyncAfter"), ("SidekickDropApp.swift", "asyncAfter"), ("SidekickVoiceLocal.swift", ".sleep("), ("SidekickVoiceLocal.swift", "Task.sleep"), ("SidekickDropApp.swift", "NSPasteboard"), ("SidekickDropApp.swift", "setString("), ("SidekickStore.swift", "UserDefaults")]
        let exceptionTokens = ["asyncAfter", ".sleep(", "Task.sleep", "NSPasteboard", "setString(", "UserDefaults"]
        for f in sidekickFiles {
            let got = exceptionTokens.map { count($0, in: live(f)) }
            let want = exceptionTokens.map { t in exact.contains { $0.file == f && $0.token == t } ? 1 : 0 }
            CT.check("\(f): the exceptions, one each where the real code needs them and none elsewhere", got, want)
        }
        let keyFile = code(source("SidekickSettings.swift")), storeFile = code(source("SidekickStore.swift"))
        CT.checkTrue("the three frozen UserDefaults keys are the only sidekick. keys, each named once, in the two files that own them", keyFile.contains("static let on = \"sidekick.on\", local = \"sidekick.local\", dismissals = \"sidekick.dismissals\"") && count("\"sidekick.", in: keyFile) + count("\"sidekick.", in: storeFile) == 3)
        CT.checkTrue("the store's one UserDefaults is its default backing, the settings' home and nothing else", storeFile.contains("init(backing: any CatSettingsBacking = UserDefaults.standard)"))
        CT.check("no file of the 21 names an agent's own folder, except the risk rule's pattern in SidekickExplain", sidekickFiles.filter { live($0).contains(".claude") }, ["SidekickExplain.swift"])
        CT.check("the ledger is memory only: nothing writes it", [count("UserDefaults", in: center), count("write(", in: center), count("JSONSerialization", in: center)], [0, 0, 0])
        CT.section("the spec gives the permission card's limit as the code does")
        let spec = (try? String(contentsOfFile: "docs/SPEC.md", encoding: .utf8)) ?? ""
        CT.checkTrue("docs/SPEC.md names the limit the app enforces (115 s, HookServer), not the hook's 120 s", hooks.contains("DispatchQueue.main.asyncAfter(deadline: .now() + 115)") && spec.contains("la limite de 115 s") && !spec.contains("la limite de 120 s"))
        CT.finish()
    }
